sys_variable_value.value:
(function execute(inputs, outputs) {

outputs.knowledge_article = null;
outputs.ai_confidence = 0;
outputs.ai_recommendation = '';
outputs.match_found = false;

var category = (inputs.category || '').toString().trim().toLowerCase();
var shortDescription = (inputs.short_description || '').toString().trim().toLowerCase();
var description = (inputs.description || '').toString().trim().toLowerCase();

if (!category) {
    outputs.ai_recommendation = 'Incident category is empty.';
    return;
}

var searchText = shortDescription + ' ' + description;

var stopWords = {
    'the': true,
    'is': true,
    'are': true,
    'was': true,
    'were': true,
    'a': true,
    'an': true,
    'and': true,
    'or': true,
    'to': true,
    'of': true,
    'on': true,
    'in': true,
    'my': true,
    'me': true,
    'this': true,
    'that': true,
    'not': true,
    'does': true,
    'do': true,
    'doesnt': true,
    'with': true,
    'for': true,
    'during': true,
    'after': true,
    'even': true,
    'when': true,
    'it': true
};

function getWords(text) {
    var words = text
        .replace(/[^a-z0-9\s]/g, ' ')
        .split(/\s+/);

    var result = [];

    for (var i = 0; i < words.length; i++) {
        var word = words[i];

        if (word.length >= 3 && !stopWords[word]) {
            result.push(word);
        }
    }

    return result;
}

var searchWords = getWords(searchText);

if (searchWords.length === 0) {
    outputs.ai_recommendation =
        'No meaningful keywords were found in the incident.';
    return;
}

var kb = new GlideRecord('kb_knowledge');

kb.addQuery('active', true);
kb.addQuery('workflow_state', 'published');
kb.query();

var bestArticle = null;
var bestScore = 0;

while (kb.next()) {

    var articleCategory = '';

    if (kb.kb_category) {
        articleCategory =
            kb.kb_category.getDisplayValue().toString().trim().toLowerCase();
    }

    if (articleCategory != category) {
        continue;
    }

    var articleTitle =
        (kb.short_description || '').toString().trim().toLowerCase();

    var articleText =
        (kb.text || '').toString().toLowerCase();

    var titleWords = getWords(articleTitle);
    var articleTextWords = getWords(articleText);

    var titleMatches = 0;
    var textMatches = 0;

    for (var i = 0; i < searchWords.length; i++) {

        var word = searchWords[i];

        if (titleWords.indexOf(word) >= 0) {
            titleMatches++;
        } else if (articleTextWords.indexOf(word) >= 0) {
            textMatches++;
        }
    }

    var score = 0;

    score += titleMatches * 30;
    score += textMatches * 5;

    if (titleMatches > 0) {
        score += 20;
    }

    if (titleMatches > 0 && score > bestScore) {
        bestScore = score;
        bestArticle = kb.getUniqueValue();
    }
}

if (!bestArticle || bestScore < 70) {

    outputs.ai_confidence = 0;
    outputs.match_found = false;
    outputs.knowledge_article = null;

    outputs.ai_recommendation =
        'No matching knowledge article was found for this incident.';

    return;
}

var confidence = bestScore;

if (confidence > 100) {
    confidence = 100;
}

outputs.knowledge_article = bestArticle;
outputs.ai_confidence = confidence;
outputs.match_found = true;

var selectedKB = new GlideRecord('kb_knowledge');

if (selectedKB.get(bestArticle)) {

    var recommendation = '';

    if (selectedKB.text) {
        recommendation = selectedKB.text.toString();
    }

    if (!recommendation && selectedKB.description) {
        recommendation = selectedKB.description.toString();
    }

    if (!recommendation) {
        recommendation =
            'Knowledge article "' +
            selectedKB.short_description.toString() +
            '" is recommended for this incident.';
    }

    outputs.ai_recommendation = recommendation;
}

})(inputs, outputs);

